/**
 * doc/cards/astrometrics/starters.md shows exactly what the starters build
 * (generated by npm run docs:astro-starters), and the three reference scenes
 * on the card's overview page are the galaxy, sector map and sky dome
 * starters, so the docs and the Studio never drift apart.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import jsYaml from 'js-yaml';
import { withStartersDoc } from '../../scripts/lib/astro-starters-doc.js';
import { STARTERS, applyStarter } from '../../src/core/astrometrics/starters/index.js';
import { starterYaml } from '../../src/core/astrometrics/starters/yaml.js';

const read = (/** @type {string} */ page) => readFileSync(new URL(`../../doc/cards/astrometrics/${page}`, import.meta.url), 'utf8');

test('starters.md is generated from the starters (run npm run docs:astro-starters)', () => {
  const page = read('starters.md');
  assert.equal(withStartersDoc(page), page);
});

test('the overview page\'s three references are the galaxy, sector map and sky dome starters', () => {
  const index = read('index.md');
  for (const [heading, id] of [['### Galaxy with territories', 'galaxy'], ['### Sector map', 'sector_map'], ['### Sky dome', 'sky_dome']]) {
    const at = index.indexOf(heading);
    assert.notEqual(at, -1, heading);
    const block = index.slice(index.indexOf('```yaml live\n', at) + 13, index.indexOf('\n```', index.indexOf('```yaml live\n', at)));
    const { type, height, ...scene } = /** @type {any} */ (jsYaml.load(block));
    const starter = STARTERS.find((s) => s.id === id);
    const built = /** @type {any} */ (applyStarter({}, /** @type {any} */ (starter))).config;
    assert.deepEqual(scene, built, `${heading} differs from the ${id} starter`);
  }
});

test('starter YAML reads back as the same config', () => {
  for (const s of STARTERS) {
    const config = /** @type {any} */ (applyStarter({ type: 'custom:lcards-astrometrics-card' }, s)).config;
    assert.deepEqual(jsYaml.load(starterYaml(config)), config, s.id);
  }
  const tricky = { points: [{ id: 'a', label: 'Qo\'noS, Kronos [capital]', tap_action: {} }], camera: { views: {} } };
  assert.deepEqual(jsYaml.load(starterYaml(tricky)), tricky);
});
